int run_lsp(std::istream&in,std::ostream&out,std::ostream&err){(void)err;bool run=true;while(run&&in){auto b=read_message(in);if(b.empty())break;json::Document m;std::string e;if(!json::Document::parse(b,m,e))continue;auto method=gs(m,"method");bool has=m.has("id");auto id=has?m["id"]:nil();if(method=="initialize"){json::Document c=json::Document::make_object();c["textDocumentSync"]=1;c["definitionProvider"]=true;c["hoverProvider"]=true;c["documentSymbolProvider"]=true;c["documentFormattingProvider"]=true;json::Document cp=json::Document::make_object(),ct=json::Document::make_array();ct.array.emplace_back(".");ct.array.emplace_back("<");cp["triggerCharacters"]=ct;c["completionProvider"]=cp;json::Document sh=json::Document::make_object(),st=json::Document::make_array();st.array.emplace_back("(");st.array.emplace_back(",");sh["triggerCharacters"]=st;c["signatureHelpProvider"]=sh;json::Document r=json::Document::make_object();r["capabilities"]=c;send(out,response(id,r));}else if(method=="shutdown")send(out,response(id,nil()));else if(method=="exit")run=false;else if(method=="textDocument/didOpen"||method=="textDocument/didChange"){auto&p=m["params"];auto&td=p["textDocument"];auto u=gs(td,"uri"),t=method=="textDocument/didOpen"?gs(td,"text"):gs(p["contentChanges"][0],"text");Doc d{u,t,uri_path(u),{}};d.root=find_project_root(d.path);docs[u]=d;publish(out,docs[u]);}else if(method=="textDocument/didClose"){auto u=gs(m["params"]["textDocument"],"uri");docs.erase(u);json::Document p=json::Document::make_object();p["uri"]=u;p["diagnostics"]=json::Document::make_array();json::Document n=json::Document::make_object();n["jsonrpc"]="2.0";n["method"]="textDocument/publishDiagnostics";n["params"]=p;send(out,n);}else if(method.rfind("textDocument/",0)==0&&has){auto&p=m["params"];auto u=gs(p["textDocument"],"uri");auto i=docs.find(u);if(i==docs.end()){send(out,response(id,nil()));continue;}auto a=analyze(u,i->second.text);if(method=="textDocument/documentSymbol")send(out,response(id,symbols(a)));else if(method=="textDocument/formatting"){json::Document ar=json::Document::make_array(),ed=json::Document::make_object();SourceSpan all;all.begin={0,1,1};std::size_t ln=1,co=1;for(char x:i->second.text){if(x=='\n'){++ln;co=1;}else++co;}all.end={i->second.text.size(),ln,co};ed["range"]=range(all);ed["newText"]=format_source_text(i->second.text);ar.push_back(ed);send(out,response(id,ar));}else{auto l=static_cast<std::size_t>(p["position"]["line"].as_int()),c=static_cast<std::size_t>(p["position"]["character"].as_int());if(method=="textDocument/completion")send(out,response(id,complete(i->second,a,l,c)));else if(method=="textDocument/hover")send(out,response(id,hover(i->second,a,l,c)));else if(method=="textDocument/signatureHelp")send(out,response(id,signatures(i->second,a,l,c)));else if(method=="textDocument/definition"){auto w=word(i->second.text,l,c);auto ds=a.defs;auto pd=project_defs(i->second);ds.insert(ds.end(),pd.begin(),pd.end());auto q=std::find_if(ds.rbegin(),ds.rend(),[&](const Def&x){return x.name==w;});send(out,response(id,q==ds.rend()?nil():location(*q)));}else send(out,response(id,nil()));}}else if(has)send(out,response(id,nil()));}return 0;}
